USE bbs_analysis;

-- =============================================
-- routes
-- =============================================

SELECT * 
FROM routes
LIMIT 5;

SELECT 
	COUNT(*)
FROM routes
WHERE 
	active = 1
	and country_num = 124;

SELECT 
	route_type_detail_id,
    COUNT(country_num)
FROM routes
WHERE 
	active = 1
	and country_num = 124
GROUP BY route_type_detail_id;


-- =============================================
-- autogenerated_points
-- =============================================

SELECT COUNT(*) AS total_points
FROM autogenerated_points; 

SELECT COUNT(DISTINCT rteno) AS total_routes
FROM autogenerated_points;

SELECT *
FROM autogenerated_points
LIMIT 5;


-- =============================================
-- stops_nearest_autogen_point
-- =============================================

SELECT COUNT(*) AS total_stops
FROM stops_nearest_autogen_point;

SELECT COUNT(DISTINCT rteno) AS total_routes
FROM stops_nearest_autogen_point;

SELECT
    rteno,
    COUNT(*) AS stop_count
FROM stops_nearest_autogen_point
GROUP BY rteno
ORDER BY stop_count, rteno;


-- =============================================
-- Test Join
-- =============================================

SELECT
    s.rteno,
    s.stop_number,
    s.nearest_autogen_num,
    p.latitude,
    p.longitude,
    s.distance_from_nearest_autogen_m
FROM stops_nearest_autogen_point AS s
JOIN autogenerated_points AS p
    ON s.rteno = p.rteno
    AND s.nearest_autogen_num = p.autogen_num
LIMIT 20;


-- =============================================
-- Bird Observations
-- =============================================

-- Erster Python-Import 

SELECT COUNT(*)
FROM bird_observations;

SELECT *
FROM bird_observations
LIMIT 10;

-- Vollständiger Import

SELECT COUNT(DISTINCT state_num)
FROM bird_observations;

-- =======================================
-- Verteilung

SELECT
    country_num,
    state_num,
    COUNT(*) AS observations
FROM bird_observations
GROUP BY country_num, state_num
ORDER BY country_num, state_num;

-- =======================================
-- Zeitraum

SELECT
    MIN(year) AS first_year,
    MAX(year) AS last_year
FROM bird_observations;


-- =======================================
-- Routen

SELECT COUNT(DISTINCT route_data_id) AS routes
FROM bird_observations;

SELECT COUNT(DISTINCT state_num, route) AS routes
FROM bird_observations;


-- =============================================
-- analysis_observations
-- =============================================

-- =======================================
-- Anzahl Einträge

SELECT 
	COUNT(*) AS observations
FROM analysis_observations;

-- =======================================
-- Anzahl Routen

SELECT 
	COUNT(DISTINCT route_id) AS routes
FROM analysis_observations;

-- =======================================
-- Anzahl Vogelarten

SELECT 
	COUNT(DISTINCT species_id) AS species
FROM analysis_observations;

-- =======================================
-- Gesamter Zählungszeitraum

SELECT 
	MIN(`year`) AS first_year,
	MAX(`year`) AS last_year
FROM analysis_observations;

-- =======================================
-- Relevanz der Spalte "protocol"

SELECT 
	protocol, 
    COUNT(*) AS observations
FROM analysis_observations
GROUP BY protocol
ORDER BY protocol;